# 你定义可用的工具
tools = [
    {
        "type": "function",
        "function": {
            "name": "get_weather",
            "description": "获取指定城市和日期的天气信息，支持查询温度、天气状况、降水等",
            "parameters": {
                "type": "object",
                "properties": {
                    "city": {
                        "type": "string",
                        "description": "城市名称，如：成都、上海、深圳"
                    },
                    "date": {
                        "type": "string",
                        "description": "日期，支持格式：今天、明天、后天、2026-01-20"
                    }
                },
                "required": ["city", "date"]
            }
        }
    }
]

# response的结构
{
    "id": "chatcmpl-xxx",
    "choices": [{
        "message": {
            "role": "assistant",
            "content": null,  # ← 没有文本回答
            "tool_calls": [   # ← 有工具调用
                {
                    "id": "call_abc123",
                    "type": "function",
                    "function": {
                        "name": "get_weather",
                        "arguments": '{"city": "成都", "date": "明天"}'
                    }
                }
            ]
        },
        "finish_reason": "tool_calls"  # ← 表示需要调用工具
    }]
}

# Bad： 描述不清晰
{
    "name": "query",
    "description": "查询",  # 太笼统，LLM不知道能查什么
    "parameters": {...}
}

# Good：描述清晰
{
    "name": "query_weather",
    "description": "查询指定城市和日期的天气信息，包括温度、天气状况、风力、降水等。支持查询
最近7天的天气预报。",
    "parameters": {...}
}

{
    "type": "object",
    "properties": {
        "city": {
            "type": "string",
            "description": "城市名称",
            "enum": ["成都", "上海", "深圳"]  # 可选：限定可选值
        },
        "date": {
            "type": "string",
            "description": "日期，格式：YYYY-MM-DD或今天/明天/后天"
        },
        "units": {
            "type": "string",
            "description": "温度单位",
            "enum": ["celsius", "fahrenheit"],
            "default": "celsius"  # 默认值
        }
    },
    "required": ["city", "date"]  # 必填参数
}

# 用户："查查魔都明天天气"
# LLM提取：city="魔都"（错误，应该是"上海"）

# 解决：在description中说明城市名称格式
{
    "city": {
        "type": "string",
        "description": "城市标准名称，如：成都、上海（不要用别称）"
    }
}

# 用户："明天天气"（没说城市）
# LLM可能无法提取city参数

# 解决1：让LLM反问用户
if 参数缺失:
    return "请问您要查询哪个城市的天气？"

# 解决2：设置默认值
{
    "city": {
        "type": "string",
        "description": "城市名称，默认成都",
        "default": "成都"
    }
}

